<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'; import LsButton from '@lostsky/ui/components/LsButton.vue'; import LsField from '@lostsky/ui/components/LsField.vue'; import LsInlineError from '@lostsky/ui/components/LsInlineError.vue'; import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue'; import LsPanel from '@lostsky/ui/components/LsPanel.vue'; import { feedback } from '@lostsky/ui/feedback'; import { useMutation,useQuery } from '@tanstack/vue-query'; import { NDatePicker,NInput,NInputNumber,NSelect,NSwitch,useDialog } from 'naive-ui'; import { computed,reactive,watch } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { canManage,manageApi } from '../../lib'
const route=useRoute();const router=useRouter();const dialog=useDialog();const id=computed(()=>Number(route.params.id||0));const editing=computed(()=>id.value>0);const form=reactive({name:'',package_id:null as number|null,claim_group:'',mode:1,total_limit:null as number|null,per_target_limit:1,range:null as [number,number]|null,is_active:1});const options=useQuery({queryKey:['manage-options'],queryFn:manageApi.options});const detail=useQuery({queryKey:computed(()=>['manage-campaign',id.value]),queryFn:()=>manageApi.campaign(id.value),enabled:editing});watch(()=>detail.data.value,d=>{if(d)Object.assign(form,{name:d.name,package_id:d.package_id,claim_group:d.claim_group,mode:Number(d.mode),total_limit:d.total_limit??null,per_target_limit:d.per_target_limit,range:d.redeem_starts_at||d.redeem_ends_at?[d.redeem_starts_at*1000,d.redeem_ends_at*1000]:null,is_active:d.is_active})},{immediate:true});const packageOptions=computed(()=>(options.data.value?.packages??[]).map(p=>({label:p.name,value:p.id,disabled:!p.is_active})));const save=useMutation({mutationFn:()=>manageApi.saveCampaign(editing.value?id.value:null,{name:form.name,package_id:form.package_id,claim_group:form.claim_group||undefined,mode:form.mode,total_limit:form.total_limit,per_target_limit:form.per_target_limit,redeem_starts_at:form.range?Math.floor(form.range[0]/1000):0,redeem_ends_at:form.range?Math.floor(form.range[1]/1000):0,is_active:form.is_active}),onSuccess:data=>{feedback.success('卡活动已保存');router.push(`/manage/campaigns/${data.id}/codes`)}});const disable=useMutation({mutationFn:()=>manageApi.disableCampaign(id.value),onSuccess:()=>router.push('/manage/campaigns')});function stop(){dialog.warning({title:'停用卡活动',content:'所有未领取卡密会立即不可用，历史领取结果保持不变。',positiveText:'确认停用',negativeText:'返回',onPositiveClick:()=>disable.mutate()})}const valid=computed(()=>Boolean(form.name.trim()&&form.package_id))
</script><template><div class="manage-page"><LsPageHeader :title="editing?'编辑卡活动':'新建卡活动'" description="模式、领取互斥组和权益包在创建后保持固定，避免已发行卡密改变语义。" back-to="/manage/campaigns" back-label="返回活动"><template #actions><RouterLink v-if="editing" class="secondary-link" :to="`/manage/campaigns/${id}/codes`">管理兑换码</RouterLink><LsButton v-if="editing&&canManage('shop.product.delete')" variant="danger" @click="stop">停用活动</LsButton></template></LsPageHeader><form class="manage-form" @submit.prevent="save.mutate()"><LsPanel><div class="form-panel"><h2>活动配置</h2><LsField label="活动名称" for-id="campaign-name" required><NInput id="campaign-name" v-model:value="form.name" maxlength="100"/></LsField><LsField label="权益包" for-id="campaign-package" required><NSelect id="campaign-package" v-model:value="form.package_id" :options="packageOptions" filterable :disabled="editing"/></LsField><LsField label="发行模式" for-id="campaign-mode" required><NSelect id="campaign-mode" v-model:value="form.mode" :options="[{label:'独立卡密',value:1},{label:'公共活动码',value:2},{label:'定向卡密',value:3}]" :disabled="editing"/></LsField><LsField label="领取互斥组" for-id="campaign-group" hint="留空时由服务端生成；公共活动可用相同组限制每个主体一次。"><NInput id="campaign-group" v-model:value="form.claim_group" :disabled="editing" maxlength="100"/></LsField><LsField label="领取时间" for-id="campaign-range"><NDatePicker id="campaign-range" v-model:value="form.range" type="datetimerange" clearable/></LsField><LsField label="总领取上限" for-id="campaign-limit" hint="留空表示不限"><NInputNumber id="campaign-limit" v-model:value="form.total_limit" :min="1" clearable/></LsField><LsField label="每个主体上限" for-id="campaign-target-limit"><NInputNumber id="campaign-target-limit" v-model:value="form.per_target_limit" :min="1"/></LsField><LsField label="启用状态" for-id="campaign-active"><NSwitch id="campaign-active" :value="form.is_active===1" @update:value="v=>form.is_active=v?1:0"/></LsField></div></LsPanel><LsInlineError v-if="detail.isError.value" :message="friendlyError(detail.error.value)"/><LsInlineError v-if="save.isError.value" :message="friendlyError(save.error.value)"/><div class="form-actions"><LsButton type="button" variant="secondary" @click="router.back()">取消</LsButton><LsButton type="submit" :disabled="!valid||!canManage('shop.product.write')" :loading="save.isPending.value">保存活动</LsButton></div></form></div></template>
